SELECT a.imsi, a.user_number, a.service_id, a.dr_type, a.start_time, a.duration, a.up_volume, a.down_volume, (SELECT COUNT(*) FROM ud.dr_ggprs_20260424 b WHERE b.imsi = a.imsi AND b.bill_date = '20260424') AS daily_cnt, (SELECT SUM(c.up_volume + c.down_volume) FROM ud.dr_ggprs_20260424 c WHERE c.imsi = a.imsi AND c.bill_date = '20260424') AS daily_volume, (SELECT MAX(d.charge) FROM ud.dr_ggprs_20260424 d WHERE d.imsi = a.imsi AND d.bill_date = '20260424') AS max_charge FROM ud.dr_ggprs_20260424 a WHERE a.bill_date = '20260424' AND a.service_id = int4(oracle.to_number('53001'::text)) AND a.duration > int4(oracle.to_number('0'::text)) ORDER BY a.start_time DESC LIMIT 50
SELECT a.imsi, a.user_number, a.service_id, a.dr_type, a.start_time, a.duration, a.up_volume, a.down_volume, (SELECT COUNT(*) FROM ud.dr_ggprs_20260424 b WHERE b.imsi = a.imsi AND b.bill_date = '20260425') AS daily_cnt, (SELECT SUM(c.up_volume + c.down_volume) FROM ud.dr_ggprs_20260424 c WHERE c.imsi = a.imsi AND c.bill_date = '20260425') AS daily_volume, (SELECT MAX(d.charge) FROM ud.dr_ggprs_20260424 d WHERE d.imsi = a.imsi AND d.bill_date = '20260425') AS max_charge FROM ud.dr_ggprs_20260424 a WHERE a.bill_date = '20260425' AND a.service_id = int4(oracle.to_number('53002'::text)) AND a.duration > int4(oracle.to_number('10'::text)) ORDER BY a.start_time DESC LIMIT 100
UPDATE ud.dr_ggprs_20260424 AS a SET charge = a.charge * ( SELECT CASE WHEN AVG(b.charge) IS NULL OR AVG(b.charge) = 0 THEN 1.0 ELSE a.charge / AVG(b.charge) END FROM ud.dr_ggprs_20260424 b WHERE b.imsi = a.imsi AND b.bill_date = '20260424' AND b.charge IS NOT NULL ), bill_flag = int4(oracle.to_number('2'::text)), process_time = (oracle.to_date('20260424235959'::text, 'YYYYMMDDHH24MISS'::text))::timestamp without time zone WHERE a.bill_date = '20260424' AND a.service_id = int4(oracle.to_number('53001'::text)) AND a.charge IS NOT NULL AND a.up_volume + a.down_volume > int4(oracle.to_number('0'::text))
