SELECT a.imsi, a.user_number, a.service_id, COALESCE((SELECT SUM(b.up_volume) FROM ud.dr_ggprs_20260424 b WHERE b.imsi = a.imsi AND b.bill_date = '20260424'), int4(oracle.to_number('0'::text))) AS total_up, COALESCE((SELECT SUM(c.down_volume) FROM ud.dr_ggprs_20260424 c WHERE c.imsi = a.imsi AND c.bill_date = '20260424'), int4(oracle.to_number('0'::text))) AS total_down FROM ud.dr_ggprs_20260424 a WHERE a.bill_date = '20260424' AND a.service_id = int4(oracle.to_number('53001'::text)) AND a.duration > int4(oracle.to_number('0'::text)) AND a.imsi IN (SELECT DISTINCT d.imsi FROM ud.dr_gsm_20260424 d WHERE d.dr_type = int4(oracle.to_number('90705'::text))) ORDER BY total_up + total_down DESC LIMIT 50
